def find_unique_pairs(lst, target_sum):
    pairs = []
    seen = set()
    for num in lst:
        diff = target_sum - num
        if diff in seen:
            pair = (min(num, diff), max(num, diff))
            if pair not in pairs:
                pairs.append(pair)
        seen.add(num)
    return pairs

def merge_dicts(d1, d2):
    result = d1.copy()
    for key, value in d2.items():
        if key in result:
            result[key] += value
        else:
            result[key] = value
    return result

