def count_elements(tup):
    # Initialize dictionary to store counts
    counts = {}

    # Iterate through tuple elements
    for element in tup:
        if element in counts:
            # Increment count if element exists
            counts[element] += 1
        else:
            # Initialize count to 1 if element is new
            counts[element] = 1

    return counts

