def count_vowels(s):
    # Define vowels
    vowels = set('aeiou')
    counts = {}

    # Iterate through string characters
    for char in s.lower():
        if char in vowels:
            if char in counts:
                counts[char] += 1
            else:
                counts[char] = 1

    return counts

