def my_function(s):
    if len(s) == 1:
        return int(s) * 2**0
    else:
        return int(s[0]) * 2**(len(s)-1) + my_function(s[1:])

def my_function(L, K):
    if len(L) == 0:
        return []
    return [L[0] - K] + my_function(L[1:], K)

def my_function(L, V):
    if len(L) == 1:
        return 0
    if L[0] == V:
        return L[1]
    else:
        return my_function(L[1:], V)

def my_function(n):
    # exceptions
    if type(n) != int or n <= 0:
        return -1
    # base case
    if n == 1:
        return 1
    # recursive call
    return (1/n) + my_function(n-1)

def my_function(lst, v):
    if len(lst) == 0:
        return 1
    if lst[0] % v == 0:
        return lst[0] * my_function(lst[1:], v)
    return 1 * my_function(lst[1:], v)

def my_function(l):
    if len(l) < 3:
        return 0
    if l[1] < l[0] and l[1] < l[2]:
        return l[1] + my_function(l[1:])
    else:
        return 0 + my_function(l[1:])

def vowelCheck(word):
    for letter in word:
        if letter in ['a', 'e', 'i', 'o', 'u']:
            return True
    return False

def my_function(L):
    if L == []:
        return 0
    else:
        thisString = L[0]
        if vowelCheck(thisString):
            return len(thisString) + my_function(L[1:])
        else:
            return 0 + my_function(L[1:])

def my_function(l):
    if len(l) == 1:
        return l[0]
    minstring = my_function(l[:-1])
    for el in l:
        if len(el) < len(minstring):
            minstring = el
    return minstring

def my_function(S):
    vowels = ['a', 'e', 'i', 'o', 'u']
    if len(S) == 0:
        return []
    if S[0] in vowels:
        return [S[0]] + my_function(S[1:])
    return [] + my_function(S[1:])

