def ascii_sum(N, S):
    for i in range(len(S)):
        for j in range(i + 1, len(S) + 1):
            # take the substring S[i:j]
            this_substring = S[i:j]
            # compute the sum of ord(letter) for each letter in the substring
            this_sum = 0
            for letter in this_substring:
                this_sum += ord(letter)
            # check if the sum is equal to N
            if this_sum == N:
                return True
    return False

