def update_employee_skills(current_skills, skill_updates):
    for employee_id, skills, action in skill_updates:

        if employee_id not in current_skills:
            current_skills[employee_id] = []

        if action == "add":
            current_skills[employee_id].extend(skills)

        elif action == "remove":
            for skill in skills:
                if skill in current_skills[employee_id]:
                    current_skills[employee_id].remove(skill)

    # Remove employees with no skills
    for employee_id in list(current_skills.keys()):
        if len(current_skills[employee_id]) == 0:
            del current_skills[employee_id]

    return current_skills

