    for i in range(n):
        for j in range(m):
            if M[i][j] < 0:
                return -2

    # take the max of the upper diagonal
    s = []
    for i in range(n - 1):
        for j in range(i + 1, i + 2):
            s.append(M[i][j])
    ma = max(s)
    # take the min of the lower diagonal
    k = []
    for i in range(1, n):
