class Auction:
    def __init__(self, item_name, minimum_bid):
        self.item_name = item_name
        self.minimum_bid = minimum_bid
        self.best_bid = minimum_bid
        self.bids = {}

    def place_bid(self, bidder, amount):
        if amount > self.best_bid:
            self.bids[bidder] = amount
            self.best_bid = amount
            return True

        return False

    def withdraw_bid(self, bidder):
        if bidder in self.bids:
            del self.bids[bidder]

            if self.bids == {}:
                self.best_bid = self.minimum_bid
            else:
                self.best_bid = max(self.bids.values())

            return True

        return False

    def get_winner(self):
        if self.bids == {}:
            return "No winner"
        else:
            for bidder, amount in self.bids.items():
                if amount == self.best_bid:
                    return bidder

