class Barrel:
    def __init__(self, _capacity):
        self.capacity = _capacity

    def draw(self, bottle_capacity):
        # if the barrel has enough capacity, draw the entire bottle capacity and update the barrel capacity
        if self.capacity >= bottle_capacity:
            self.capacity -= bottle_capacity
            return bottle_capacity
        # if the barrel has less capacity than the bottle, draw the entire barrel capacity and set its capacity to 0
        drawned = self.capacity
        self.capacity = 0
