def safe_read_numbers(path):
    try:
        with open(path, 'r') as f:
            result = []
            for line in f:
                text = line.strip()
                if not text:
                    continue
                try:
                    value = int(text)
                    result.append(value)
                except ValueError as e:
                    print('Skipping invalid line:', text, '-', e)
            return result
    except FileNotFoundError:
        print('File not found:', path)
        return []

