JSONBin.io requires a free account: copy your X-Master-Key from the API Keys page and store it in the JSONBIN_KEY environment variable.

import os
import requests

def create_bin(data):
    """Create a JSON storage bin using JSONBin.io API"""
    url = 'https://api.jsonbin.io/v3/b'

    # Set headers (JSONBin requires an API key to create a bin)
    headers = {
        'Content-Type': 'application/json',
        'X-Master-Key': os.environ['JSONBIN_KEY']
    }

    try:
        # Make POST request with JSON data
        response = requests.post(url, json=data, headers=headers, timeout=10)

        # Check if successful
        if response.status_code in [200, 201]:
            # Extract bin ID from the response
            bin_id = response.json()['metadata']['id']
            return {
                'success': True,
                'bin_id': bin_id,
                'url': f'https://api.jsonbin.io/v3/b/{bin_id}',
                'error': None
            }
        else:
            return {
                'success': False,
                'bin_id': None,
                'url': None,
                'error': f'{response.status_code}: {response.text}'
            }

    except requests.exceptions.RequestException as e:
        return {'success': False, 'bin_id': None, 'url': None, 'error': str(e)}

# Test the function
test_data = {
    'name': 'John Doe',
    'age': 30,
    'city': 'Rome'
}

result = create_bin(test_data)
print(f"Success: {result['success']}")
if result['success']:
    print(f"Bin ID: {result['bin_id']}")
    print(f"URL: {result['url']}")
else:
    print(f"Error: {result['error']}")



NOTE: When using requests.post() with the json parameter:

The data is automatically serialized to JSON

The Content-Type header is automatically set to application/json

You don't need to call json.dumps() manually

Any other header you pass (like X-Master-Key) is kept and sent along

import requests

def get_weather_safe(city, api_key):
    """Fetch weather data with comprehensive error handling"""
    url = 'https://api.openweathermap.org/data/2.5/weather'

    params = {
        'q': city,
        'appid': api_key,
        'units': 'metric'
    }

    try:
        # Make GET request with timeout
        response = requests.get(url, params=params, timeout=10)

        # Get status code
        status_code = response.status_code

        # Handle different status codes
        if status_code == 200:
            # Success - parse data
            try:
                data = response.json()
                return {
                    'success': True,
                    'error': None,
                    'status_code': status_code,
                    'data': {
                        'city': data['name'],
                        'temperature': data['main']['temp'],
                        'description': data['weather'][0]['description']
                    }
                }
            except (KeyError, ValueError):
                return {
                    'success': False,
                    'error': 'Failed to parse API response',
                    'status_code': status_code,
                    'data': None
                }

        elif status_code == 401:
            return {
                'success': False,
                'error': 'Invalid API key. Please check your credentials.',
                'status_code': status_code,
                'data': None
            }

        elif status_code == 404:
            return {
                'success': False,
                'error': f'City "{city}" not found. Please check the spelling.',
                'status_code': status_code,
                'data': None
            }

        elif status_code == 429:
            return {
                'success': False,
                'error': 'Too many requests. Please wait and try again later.',
                'status_code': status_code,
                'data': None
            }

        elif status_code >= 500:
            return {
                'success': False,
                'error': 'Server error. Please try again later.',
                'status_code': status_code,
                'data': None
            }

        else:
            return {
                'success': False,
                'error': f'Unexpected error (status code: {status_code})',
                'status_code': status_code,
                'data': None
            }

    except requests.exceptions.Timeout:
        return {
            'success': False,
            'error': 'Request timeout. Please check your internet connection.',
            'status_code': None,
            'data': None
        }

    except requests.exceptions.ConnectionError:
        return {
            'success': False,
            'error': 'Connection error. Please check your internet connection.',
            'status_code': None,
            'data': None
        }

    except Exception as e:
        return {
            'success': False,
            'error': f'Unexpected error: {str(e)}',
            'status_code': None,
            'data': None
        }

# Test with invalid API key (401 error)
result = get_weather_safe('London', 'invalid_api_key_12345')
print(f"Success: {result['success']}")
print(f"Status Code: {result['status_code']}")
print(f"Error: {result['error']}")



BEST PRACTICES for error handling:

Always check status codes before processing data

Provide user-friendly error messages

Handle network errors (timeout, connection failures)

Use try-except blocks for JSON parsing

Set timeouts for requests to prevent hanging

You can handle different exceptions differently, or group them in a tuple.

def safe_divide(a, b):
    try:
        return a / b
    except ZeroDivisionError as e:
        print('Cannot divide by zero:', e)
        return None
    except TypeError as e:
        print('Wrong types:', e)
        return None

print(safe_divide(10, 0))
print(safe_divide('10', 5))
print(safe_divide(10, 2))

Use raise to signal invalid states or inputs from your own code.

def set_age(age):
    if age < 0:
        raise ValueError('age must be non-negative')
    return age

try:
    set_age(-3)
except ValueError as e:
    print('Error:', e)

Create domain-specific exceptions by subclassing Exception.

class InvalidGradeError(Exception):
    pass

def record_grade(student, grade):
    if not (0 <= grade <= 30):
        raise InvalidGradeError(f'grade {grade} out of range 0..30')
    return { 'student': student, 'grade': grade }

try:
    record_grade('Alice', 35)
except InvalidGradeError as e:
    print('Custom error:', e)

Use traceback to capture the stack trace for logs or error reports.

import traceback

def divide(a, b):
    return a / b

try:
    divide(3, 0)
except Exception:
    tb = traceback.format_exc()
    print('Traceback captured for logs:
', tb)

Design functions that validate inputs and report errors clearly.

def average(values):
    if not values:
        raise ValueError('values must be a non-empty iterable')
    try:
        total = sum(values)
        count = len(values)
        return total / count
    except TypeError as e:
        raise TypeError('values must be numbers') from e

try:
    print('avg:', average([10, 20, 30]))
    print('avg:', average([]))
except Exception as e:
    print('Handled:', e)



NOTE: Use raise ... from e to preserve the original cause while adding context.
